			resolveConnect();
			await connect;
		});
		await waitFor(() =>
			expect(bridge.callServerTool).toHaveBeenCalledWith({
				name: "restore_lobu_app_result",
				arguments: { tool_call_id: "late-card", tool_name: "query_sdk" },
			}),
		);
		await waitFor(() => expect(screen.getByTestId("state")).toHaveTextContent("true"));
	});
